const campaigns = $input.all().map(i => i.json);
if (!campaigns.length || !campaigns[0].id) return [{ json: { no_data: true } }];

// Estimated cost per email (configurable)
const costPerEmail = 0.005; // $0.005 per email via SendGrid
const fixedMonthlyCost = 500000; // Rp 500k platform cost

const campaignResults = campaigns.map(c => {
  const sent = parseInt(c.total_sent) || 0;
  const opened = parseInt(c.total_opened) || 0;
  const clicked = parseInt(c.total_clicked) || 0;
  const conversions = parseInt(c.total_conversions) || 0;
  const revenue = parseFloat(c.revenue_attributed) || 0;

  const cost = sent * costPerEmail * 15000; // Convert to IDR
  const roi = cost > 0 ? ((revenue - cost) / cost * 100) : 0;

  return {
    campaign_id: c.id,
    campaign_name: c.campaign_name,
    campaign_type: c.campaign_type,
    status: c.status,
    metrics: {
      sent: sent,
      opened: opened,
      clicked: clicked,
      conversions: conversions,
      open_rate: sent > 0 ? (opened / sent * 100).toFixed(1) : '0',
      click_rate: sent > 0 ? (clicked / sent * 100).toFixed(1) : '0',
      conversion_rate: sent > 0 ? (conversions / sent * 100).toFixed(2) : '0'
    },
    financials: {
      cost_idr: Math.round(cost),
      revenue_idr: Math.round(revenue),
      profit_idr: Math.round(revenue - cost),
      roi_percent: Math.round(roi)
    }
  };
});

// Summary
const totalCost = campaignResults.reduce((sum, c) => sum + c.financials.cost_idr, 0) + fixedMonthlyCost;
const totalRevenue = campaignResults.reduce((sum, c) => sum + c.financials.revenue_idr, 0);
const totalConversions = campaignResults.reduce((sum, c) => sum + c.metrics.conversions, 0);
const overallROI = totalCost > 0 ? ((totalRevenue - totalCost) / totalCost * 100) : 0;

// Top performers
const topByROI = [...campaignResults].filter(c => c.financials.revenue_idr > 0).sort((a, b) => b.financials.roi_percent - a.financials.roi_percent).slice(0, 5);
const topByConversions = [...campaignResults].sort((a, b) => b.metrics.conversions - a.metrics.conversions).slice(0, 5);

return [{
  json: {
    period: 'Last 30 days',
    summary: {
      total_campaigns: campaignResults.length,
      total_cost_idr: totalCost,
      total_revenue_idr: totalRevenue,
      total_profit_idr: totalRevenue - totalCost,
      overall_roi_percent: Math.round(overallROI),
      total_conversions: totalConversions,
      cost_per_conversion: totalConversions > 0 ? Math.round(totalCost / totalConversions) : 0
    },
    top_by_roi: topByROI,
    top_by_conversions: topByConversions,
    all_campaigns: campaignResults
  }
}];

